use std::fs

struct Tree {
    keys: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
    found: bool,
}

impl Tree {
    fn has(self, x: int) -> bool {
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if k == x { return true }
            if x < k { cur = self.left[cur as usize] } else { cur = self.right[cur as usize] }
        }
        false
    }

    fn add(self, x: int) {
        self.keys.push(x)
        self.left.push(-1)
        self.right.push(-1)
        let id: int = (self.keys.len() as int) - 1
        if self.root < 0 {
            self.root = id
            return
        }
        let mut cur = self.root
        loop {
            let k = self.keys[cur as usize]
            if x < k {
                let l = self.left[cur as usize]
                if l < 0 {
                    self.left[cur as usize] = id
                    return
                }
                cur = l
            } else {
                let r = self.right[cur as usize]
                if r < 0 {
                    self.right[cur as usize] = id
                    return
                }
                cur = r
            }
        }
    }

    fn minnode(self, n: int) -> int {
        let mut cur = n
        while self.left[cur as usize] >= 0 { cur = self.left[cur as usize] }
        cur
    }

    fn del(self, n: int, x: int) -> int {
        if n < 0 { return -1 }
        let k = self.keys[n as usize]
        if x < k {
            let r = self.del(self.left[n as usize], x)
            self.left[n as usize] = r
            return n
        }
        if x > k {
            let r = self.del(self.right[n as usize], x)
            self.right[n as usize] = r
            return n
        }
        self.found = true
        let l = self.left[n as usize]
        let r = self.right[n as usize]
        if l < 0 { return r }
        if r < 0 { return l }
        let s = self.minnode(r)
        let sk = self.keys[s as usize]
        self.keys[n as usize] = sk
        let nr = self.del(r, sk)
        self.right[n as usize] = nr
        n
    }

    fn height(self, n: int) -> int {
        if n < 0 { return 0 }
        let a = self.height(self.left[n as usize])
        let b = self.height(self.right[n as usize])
        if a > b { a + 1 } else { b + 1 }
    }

    fn walk(self, n: int, out: Vec<int>) -> Vec<int> {
        if n < 0 { return out }
        let mut o = self.walk(self.left[n as usize], out)
        o.push(self.keys[n as usize])
        self.walk(self.right[n as usize], o)
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], left: [], right: [], root: -1, found: false }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").collect()
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.has(x) { println("dup") } else {
                t.add(x)
                println("ok")
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.has(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            t.found = false
            let r = t.root
            let nr = t.del(r, x)
            t.root = nr
            if t.found { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            let v = t.walk(t.root, [])
            if v.len() == 0 { println("<empty>") } else {
                let mut s = ""
                let mut first = true
                for k in v {
                    if !first { s = s + " " }
                    first = false
                    s = s + "${k}"
                }
                println(s)
            }
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" {
            if t.root < 0 { println("empty") } else {
                println("${t.keys[t.minnode(t.root) as usize]}")
            }
        } else if cmd == "max" {
            if t.root < 0 { println("empty") } else {
                let mut c = t.root
                while t.right[c as usize] >= 0 { c = t.right[c as usize] }
                println("${t.keys[c as usize]}")
            }
        }
    }
}

